function initialPolygon () {
  let m = max(width, height)*margin;
	if (renderAs == "expanded" || renderAs == "hobbyExpanded") m *= 4;
  let poly;
  if (startShape == "rectangle") {
    poly = [createVector(m,m),
             createVector(width-m,m),
             createVector(width-m,height-m),
             createVector(m,height-m)];
  } else if (startShape == "polygon") {
    let r = max(width, height) / 2 - m;
    let center = createVector(width/2, height/2);
    if (startPolygonSides == 3) center.y+=r/6;
    let v = createVector (0,-r);
    poly = [];
    for (let i = 0; i < startPolygonSides; i++) {
      poly.push (center.copy().add(v));
      v.rotate(TWO_PI/startPolygonSides);
    }
  }
  return poly;
}


