function subdivide_polygon_opt (points, recursions = 0) {
  let centroid = calculateCentroid(points);

  var r = calculateMinDistanceToBoundary (centroid, points);

  let vector = createVector(1,0);
  vector.rotate(random(TWO_PI));
  centroid.add(vector.setMag(random(0.1,r*deviation)))
  let dang = PI / tries;
  let result = [];
  let best = -1;
  for (let i = 0; i < tries; i++) {
    vector.rotate(dang);
    let [a,b] = splitPolygon(points,centroid,vector);
    let reg = measureRegularity(a)+
        measureRegularity(b);
    if (reg > best) {
      result = [a,b];
      best = reg;
    }
  }
  let recur = () => {
    for (let i = 0; i < recursions; i++) 
      if (random() < chanceRecursion) return true;
  }
  if (recursions>0) {
    let [a,b] = result;
    result = [];
    if (recur()) 
      result.push (...subdivide_polygon_opt(a,recursions-1))
    else
      result.push (a);
    if (recur()) 
      result.push (...subdivide_polygon_opt(b,recursions-1))
    else
      result.push (b);
  }
  return result;
}

