function makePalette(nc, parameters) {
  let p = [];
	let {satMin,satMax,valMin,valMax,hStart,
  	   hSpread,sgn,power} = parameters || randomPaletteParameters();
  let hDelta = 1/nc*hSpread;
  let pwr = (x) => sgn*(x**power);
  // print (JSON.stringify ({satMin,satMax,valMin,valMax,
  //                         hStart,hSpread,sgn,exp}));
  let H = [], S=[], L=[];
  for (let i = 0; i < nc; i++) {
    let h = (hStart + hDelta*i) % 1;
    let a = pwr(i / (nc-1));
    let b = pwr(1)
    let s = map(a,0,b,satMin,satMax);
    let l = map(a,0,b,valMax,valMin);
    H.push(h); S.push(s); L.push(l);
  }
  shuffle(H,true)
  //S = [S[0],...shuffle(S.slice(1))]
  push();
  colorMode (RGB,255);
	let spaceFunc = ({okhsl:okhsl_to_srgb,
										okhsv:okhsv_to_srgb,
										hsl: hsl_to_rgb,
										hsv: hsv_to_rgb})[colorSpace];
  for (let i = 0; i < nc; i++) {
    let [r, g, b] = spaceFunc (H[i],S[i],L[i])
    p.push(color(r,g,b))
  }
  pop();
  return p;
}

function midPoints (points) {
	let n = points.length;
  var b = points[n-1];
  var p = [];
  for (let i = 0; i < n; i++) {
    var a = points[i];
    p.push (createVector ((a.x + b.x)/2, (a.y+b.y)/2));
    b = a;
  }
	return p;
}

