function drawAsHobby (points) {
	let bezier = createHobbyBezier(points, {
      tension: tightness < 0 ? 
				map(tightness,-5,0,0.7,1) :
		    map(tightness,0,5,1,10),
      cyclic: true
    });
	beginShape();
	vertex (points[0].x, points[0].y);
	for (let { startControl, endControl, point } of bezier) {
      bezierVertex (
        startControl.x,
        startControl.y,
        endControl.x,
        endControl.y,
        point.x,
        point.y
      );
  }
	endShape(CLOSE);
}

function starShape (points) {
	var c = calculateCentroid(points);
  var r = calculateMinDistanceToBoundary (c, points);
	var n = points.length;
  var b = points[n-1];
  var p = [];
  for (let i = 0; i < n; i++) {
    var a = points[i];
    let mid = createVector ((a.x + b.x)/2, (a.y+b.y)/2);
    let q = mid.sub(c).setMag(r/2).add(c);
		p.push (b, q)
		b = a
  }
	return p;
}

