function calculateCentroid(points) {
  let area = 0;
  let centroidX = 0;
  let centroidY = 0;

  for (let i = 0; i < points.length; i++) {
    let j = (i + 1) % points.length;
    let xi = points[i].x;
    let yi = points[i].y;
    let xj = points[j].x;
    let yj = points[j].y;
    let factor = xi * yj - xj * yi;
    area += factor;
    centroidX += (xi + xj) * factor;
    centroidY += (yi + yj) * factor;
  }

  area = 0.5 * area;
  centroidX = (1 / (6 * area)) * centroidX;
  centroidY = (1 / (6 * area)) * centroidY;

  return createVector(centroidX, centroidY);
}

// 
// ChatGPT prompt:
//
// What would be a good way of measuring how regular is a
// polygon? For instance, a regular polygon would yield a
// measure of 1, while a polygon with zero area would
// yield 0. Try to state this as a p5.js function
//

// Function to compute the regularity measure of a polygon
function measureRegularity(polygon) {
  var n = polygon.length;
  if (n < 3) return 0; // Degenerate polygons with less than 3 vertices have zero regularity

  // Calculate perimeter
  let perimeter = 0;
  for (let i = 0; i < n; i++) {
    var next = (i + 1) % n;
    perimeter += p5.Vector.dist(polygon[i], polygon[next]);
  }

  // Calculate area
  var area = polygonArea(polygon);

  // Calculate maximum possible area for a regular polygon with the same perimeter
  let maxArea = (perimeter * perimeter) / (4 * n * tan(PI / n));

  // Regularity measure as the ratio between actual area and maximum area
  let regularity = area / maxArea;

  return constrain(regularity, 0, 1); // Ensure the value is within [0, 1]
}

// Function to calculate the area of a polygon using the shoelace formula
function polygonArea(polygon) {
  var n = polygon.length;
  var area = 0;

  for (let i = 0; i < n; i++) {
    var next = (i + 1) % n;
    area += polygon[i].x * polygon[next].y - polygon[next].x * polygon[i].y;
  }

  return abs(area) / 2;
}

//
// Gemini Prompt
//
// Can you write me a p5.js function that, given a 
// convex polygon as an array of points and 
// a point p inside it, returns the minimal distance 
// to the boundary of the polygon, i.e., 
// the minimal distance to one of its edges?
//
function calculateMinDistanceToBoundary(point, polygon) {
  let minDistance = Infinity;

  for (let i = 0; i < polygon.length; i++) {
    var j = (i + 1) % polygon.length;

    let p1 = polygon[i];
    let p2 = polygon[j];

    let edge = p5.Vector.sub(p2, p1);
    let pointToEdge = p5.Vector.sub(point, p1);

    let projection = pointToEdge.dot(edge) / edge.magSq();
    let closestPointOnEdge = p5.Vector.add(p1, edge.mult(projection));

    let distance = p5.Vector.dist(point, closestPointOnEdge);
    minDistance = Math.min(minDistance, distance);
  }

  return minDistance;
}

