// Helper function to check on which side of the line a point lies
// Positive return: "inside", Negative return: "outside"
function sideOfLine(point, p, v) {
  let perpendicular = createVector(-v.y, v.x); // Perpendicular to the direction vector
  let diff = p5.Vector.sub(point, p); // Vector from p to the point
  return diff.dot(perpendicular); // Dot product: positive, negative, or zero
}

// Function to compute the intersection point between the line and polygon edge
function intersectSegment(p1, p2, p, v) {
  let edgeVec = p5.Vector.sub(p2, p1);
  let lineToEdgeVec = p5.Vector.sub(p1, p);

  let crossProduct = v.x * edgeVec.y - v.y * edgeVec.x;

  if (abs(crossProduct) < 0.0001) return null; // Parallel lines, no intersection

  let t = (lineToEdgeVec.x * edgeVec.y - lineToEdgeVec.y * edgeVec.x) / crossProduct;
  var u = (lineToEdgeVec.x * v.y - lineToEdgeVec.y * v.x) / crossProduct;

  if (u >= 0 && u <= 1) {
    return createVector(p.x + t * v.x, p.y + t * v.y);
  }
  return null; // No valid intersection within the edge
}

// Sutherland-Hodgman algorithm to clip the polygon
function clipPolygon(polygon, p, v) {
  let clippedPolygon = [];
  for (let i = 0; i < polygon.length; i++) {
    let curr = polygon[i];
    var next = polygon[(i + 1) % polygon.length];

    let currSide = sideOfLine(curr, p, v);
    let nextSide = sideOfLine(next, p, v);

    if (currSide >= 0) {
      clippedPolygon.push(curr); // Current vertex is inside
    }

    // If the edge crosses the line, add the intersection point
    if ((currSide >= 0 && nextSide < 0) || (currSide < 0 && nextSide >= 0)) {
      let intersection = intersectSegment(curr, next, p, v);
      if (intersection) {
        clippedPolygon.push(intersection);
      }
    }
  }
  return clippedPolygon;
}

function splitPolygon(polygon, p, v) {
  // Clip the polygon with respect to the line
  let poly1 = clipPolygon(polygon, p, v);         // Above or on the line
  let poly2 = clipPolygon(polygon, p, p5.Vector.mult(v, -1)); // Below or on the line

  return [poly1, poly2];
}

