function hex_to_rgb(hex)
{
    if (hex.substr(0,1) == "#")
        hex = hex.substr(1);

    if (hex.match(/^([0-9a-f]{3})$/i)) 
    {
        var r = parseInt(hex.charAt(0),16)/15 * 255;
        var g = parseInt(hex.charAt(1),16)/15 * 255;
        var b = parseInt(hex.charAt(2),16)/15 * 255;
        return [r,g,b];
    }
    if (hex.match(/^([0-9a-f]{6})$/i)) 
    {
        var r = parseInt(hex.substr(0,2),16);
        var g = parseInt(hex.substr(2,2),16);
        var b = parseInt(hex.substr(4,2),16);
        return [r,g,b];
    }
    if (hex.match(/^([0-9a-f]{1})$/i)) 
    {
        var a = parseInt(hex.substr(0),16)/15 * 255;
        return [a,a,a];
    }
    if (hex.match(/^([0-9a-f]{2})$/i)) 
    {
        var a = parseInt(hex.substr(0,2),16);
        return [a,a,a];
    }

    return null;
}

function rgb_to_hex(r,g,b)
{
    function componentToHex(x) 
    {
        var hex = Math.round(x).toString(16);
        return hex.length == 1 ? "0" + hex : hex;
    }

    return "#" + componentToHex(r) + componentToHex(g) + componentToHex(b); 
}

